{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  let debug = [];

  try {
    await page.setViewport({ width: 1280, height: 800 });

    // LOGIN
    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'networkidle2', timeout: 30000 });
    debug.push('1-login page');
    await w(1000);

    const eInp = await page.$('#email_principal');
    if (eInp) { 
      await eInp.click(); 
      await eInp.type(EMAIL, { delay: 20 }); 
      debug.push('2-email ok');
    } else {
      debug.push('2-email NOT FOUND');
    }
    await w(500);

    await page.evaluate(() => { 
      const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Continuar com Email')); 
      if(b) b.click(); 
    });
    debug.push('3-continuar clicked');

    await page.waitForSelector('#pwdInput', { timeout: 10000 });
    const sInp = await page.$('#pwdInput');
    if (sInp) { 
      await sInp.click(); 
      await sInp.type(SENHA, { delay: 20 }); 
      debug.push('4-senha ok');
    }
    await w(500);

    await page.evaluate(() => { 
      const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Entrar'); 
      if(b) b.click(); 
    });
    debug.push('5-entrar clicked');
    await w(4000);

    // Check if logged in
    const urlAfterLogin = page.url();
    debug.push('6-url: ' + urlAfterLogin.substring(0, 50));

    // Hapvida click
    const hapClicked = await page.evaluate(() => { 
      const img = document.querySelector('img[src*=\"hapvida\"]'); 
      if(img) { 
        const p = img.closest('.clickable-element') || img.parentElement.parentElement; 
        if(p) { p.click(); return true; }
      } 
      return false;
    });
    debug.push('7-hapvida: ' + hapClicked);
    await w(2000);

    // FORM PAGE
    await page.goto('https://app.cotadorsimplificado.com.br/?produto=hap', { waitUntil: 'domcontentloaded', timeout: 30000 });
    debug.push('8-form page');
    await w(2000);

    // Check what's on the page
    const pageCheck = await page.evaluate(() => {
      const text = document.body.innerText.substring(0, 300);
      const hasPME = text.includes('PME');
      const hasLogin = text.includes('login') || text.includes('Email');
      const clickables = document.querySelectorAll('.clickable-element').length;
      return { hasPME, hasLogin, clickables, text: text.substring(0, 150) };
    });
    debug.push('9-hasPME: ' + pageCheck.hasPME + ' hasLogin: ' + pageCheck.hasLogin + ' clickables: ' + pageCheck.clickables);

    // PME click
    const pmeClicked = await page.evaluate(() => { 
      const p = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29')); 
      if(p) { p.click(); return true; }
      return false;
    });
    debug.push('10-PME clicked: ' + pmeClicked);
    await w(1500);

    // Check for nome input
    const hasNomeInput = await page.$('#id-nomelead');
    debug.push('11-nomeInput exists: ' + !!hasNomeInput);

    // Take screenshot
    const screenshot = await page.screenshot({ encoding: 'base64' });
    const pageText = await page.evaluate(() => document.body.innerText.substring(0, 800));

    return { success: true, debug, screenshot, pageText };
  } catch (error) {
    const screenshot = await page.screenshot({ encoding: 'base64' }).catch(() => null);
    return { success: false, error: error.message, debug, screenshot };
  }
}"
}
